<script setup lang="ts">
import { computed, ref } from 'vue'
import type { ImportPreviewResult, ImportSetPlan } from '../../api/importer'
import { previewSummary } from './importLabels'
const props = defineProps<{ plan: ImportSetPlan | null; drafts: Array<ImportPreviewResult & { filename: string }>; uploadErrors: string[]; failuresExcluded: boolean; busy: boolean; canConfirm: boolean }>()
const emit = defineEmits<{ remove: [id: string]; retry: []; restart: []; confirm: []; 'exclude-failures': [] }>()
type ReviewFile = ImportSetPlan['files'][number]
const selected = ref<ReviewFile | null>(null), detailPage = ref(1)
const rows = computed(() => props.plan?.files || props.drafts.map(d => ({ id: d.id, filename: d.filename, target: d.target, summary: d.summary || {}, changes: [], issues: [...(d.errors || []), ...(d.warnings || [])] })))
const blocked = (file: ReviewFile) => file.issues.some(i => i.severity === 'error')
const blockedCount = computed(() => rows.value.filter(blocked).length)
const counts = computed(() => { const changes = rows.value.flatMap(row => row.changes); return { create: changes.filter(c => c.action === 'CREATE').length, update: changes.filter(c => c.action === 'UPDATE').length, unchanged: changes.filter(c => c.action === 'UNCHANGED').length } })
const people = computed(() => rows.value.reduce((total, row) => ({ create: total.create + Number(row.summary.person_links_create || 0), existing: total.existing + Number(row.summary.person_links_existing || 0), pending: total.pending + Number(row.summary.person_links_pending || 0) }), { create: 0, existing: 0, pending: 0 }))
const summary = (row: ReviewFile) => previewSummary(row.target, row.summary) || `${row.changes.length} 项核对内容`
const fields: Record<string, string> = { staff_no: '工号', duty: '职责', effective_from: '生效日期', effective_to: '结束日期（当日不再生效）', name: '姓名', class_name: '班级', class_code: '教学班码', course_name: '课程', weekday: '星期', start_period: '开始节次', end_period: '结束节次', weeks: '周次', classroom: '教室', teacher: '任课教师', teacher_staff_no: '教师工号', head_teacher: '班主任', counselor: '辅导员', college: '学院', enabled: '启用', student_nos: '学号', present: '在名单中' }
const labels = { CREATE: '新增', UPDATE: '修改', UNCHANGED: '无变化' }
function describe(value: Record<string, unknown> | null) { if (!value) return '无原资料'; return Object.entries(value).filter(([key]) => !['kind', 'staff_id', 'action'].includes(key)).map(([key, val]) => `${fields[key] || key}：${val === 'HEAD_TEACHER' ? '班主任' : val === 'COUNSELOR' ? '辅导员' : Array.isArray(val) ? val.join('、') : typeof val === 'boolean' ? val ? '是' : '否' : val ?? '未填写'}`).join('\n') }
function detail(row: ReviewFile) { selected.value = row; detailPage.value = 1 }
</script>

<template>
  <section class="review" aria-label="文件导入预览">
    <header class="review-head"><div><h2>先看结果，再确认导入</h2><p>已读取 {{ rows.length }} 个表格<template v-if="blockedCount">，{{ blockedCount }} 个需要处理</template><template v-else-if="plan">，未发现阻断问题</template>。正式资料尚未保存。</p></div><el-button :disabled="busy" @click="emit('restart')">重新选择文件</el-button></header>
    <div v-if="plan" class="change-summary"><span>新增 <strong>{{ counts.create }}</strong> 项</span><span>修改 <strong>{{ counts.update }}</strong> 项</span><span>无变化 <strong>{{ counts.unchanged }}</strong> 项</span></div>
    <p v-if="people.create || people.existing || people.pending" class="hint">人员关联：可自动建立 {{ people.create }} 项，已有 {{ people.existing }} 项，待处理 {{ people.pending }} 项（同一关系涉及多个文件时只保存一次）。待关联不会阻止课表保存，也不会开放对应的教师权限；请在文件详情中查看原因。</p>
    <el-alert v-for="message in uploadErrors" :key="message" :title="`未读入：${message}`" type="error" :closable="false" /><el-alert v-if="uploadErrors.length && !failuresExcluded" title="失败文件不会被悄悄跳过。可重新选择文件，或明确排除失败文件后仅导入下列资料。" type="warning" :closable="false" /><el-button v-if="uploadErrors.length && !failuresExcluded" :disabled="busy" @click="emit('exclude-failures')">本次不导入以上失败文件</el-button><p v-if="uploadErrors.length && failuresExcluded" class="hint">已明确排除 {{ uploadErrors.length }} 个失败文件；本次只导入下表中的文件。</p>
    <div class="file-list"><article v-for="file in rows" :key="file.id" class="file-row"><div class="file-content"><strong class="filename">{{ file.filename }}</strong><p>{{ summary(file) }}</p><p v-if="blocked(file)" class="problem">需要处理：{{ file.issues.find(i => i.severity === 'error')?.message }}</p><p v-else-if="file.issues.length" class="warning">有 {{ file.issues.length }} 项提示，请核对后导入。</p><p v-else class="ready">{{ plan ? '可以导入' : '已读取，等待核对' }}</p></div><div class="row-actions"><el-button v-if="plan" link @click="detail(file)">{{ file.issues.length ? '查看问题与内容' : '查看内容' }}</el-button><el-button link :disabled="busy" @click="emit('remove', file.id)">本次不导入</el-button></div></article></div>
    <p v-if="blockedCount" class="problem">请处理以上问题，或明确移除对应文件；处理完成前不会保存。</p><p class="hint">{{ plan?.impact_note || '请核对本批资料。' }} 未出现在文件中的已有学生名单不会因此删除。</p><footer class="confirm-actions"><el-button v-if="!plan" :disabled="busy || rows.length > 100" @click="emit('retry')">重新核对这批文件</el-button><el-button type="primary" size="large" :disabled="!canConfirm" @click="emit('confirm')">确认导入 {{ rows.length }} 个文件</el-button><span class="hint">点击后才保存上面的新增与修改。</span></footer>
    <el-dialog :model-value="!!selected" :title="selected?.filename || '文件内容'" width="min(900px, 94vw)" @close="selected = null"><template v-if="selected"><p>{{ summary(selected) }}</p><section v-if="selected.issues.length"><h3>需要核对的地方</h3><p v-for="(issue, index) in selected.issues" :key="index" :class="issue.severity === 'error' ? 'problem' : 'warning'">{{ issue.row ? `第 ${issue.row} 行 · ` : '' }}{{ issue.field || '' }} {{ issue.message }}</p></section><h3 class="detail-heading">将保存的内容</h3><el-table :data="selected.changes.slice((detailPage - 1) * 30, detailPage * 30)" empty-text="没有可导入的内容"><el-table-column label="处理" width="90"><template #default="{ row }">{{ labels[row.action as keyof typeof labels] }}</template></el-table-column><el-table-column label="来源" width="130"><template #default="{ row }">{{ row.source.sheet || '表格' }}{{ row.source.row ? ` · 第${row.source.row}行` : '' }}</template></el-table-column><el-table-column label="导入后"><template #default="{ row }"><pre>{{ describe(row.after) }}</pre><details v-if="row.action === 'UPDATE'"><summary>查看修改前</summary><pre>{{ describe(row.before) }}</pre></details></template></el-table-column></el-table><el-pagination v-model:current-page="detailPage" :page-size="30" :total="selected.changes.length" layout="prev, pager, next, total" /></template></el-dialog>
  </section>
</template>

<style scoped>
.review { margin-top:20px; }.review-head { display:flex;align-items:flex-start;justify-content:space-between;gap:16px; }.review-head h2 { font-size:18px;margin-bottom:6px; }.review-head p,.hint,.file-content p { font-size:13px;color:var(--ink-mute); }.change-summary { display:flex;gap:26px;margin:20px 0;font-size:14px; }.change-summary strong { font-size:20px;color:var(--ink); }.file-list { border-top:1px solid var(--line);margin:16px 0; }.file-row { display:flex;justify-content:space-between;gap:16px;padding:16px 0;border-bottom:1px solid var(--line); }.file-content { min-width:0; }.filename { overflow-wrap:anywhere;font-size:14px; }.file-content p { margin-top:5px; }.row-actions { display:flex;gap:10px;align-items:center;flex-shrink:0; }.file-content .problem,.problem { color:var(--red, #b42318); }.file-content .ready { color:var(--green, #18794e); }.file-content .warning,.warning { color:var(--amber, #946200); }.confirm-actions { display:flex;align-items:center;gap:14px;margin:22px 0;flex-wrap:wrap; }.el-alert { margin:12px 0; }pre { white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px; }.detail-heading { margin-top:18px; }.el-pagination { margin-top:12px; }@media(max-width:700px) { .file-row { flex-direction:column;gap:5px; }.row-actions { justify-content:flex-end; }.change-summary { gap:16px; } }
</style>
